def gate(results, max_flaky=0):
    g = lambda k: results.get(k, 0)
    reasons = []
    if g('failed') > 0:
        reasons.append('failed tests')
    if g('errors') > 0:
        reasons.append('errors')
    if g('flaky') > max_flaky:
        reasons.append('too many flaky')
    if g('passed') + g('failed') + g('errors') == 0:
        reasons.append('no tests ran')
    return (1 if reasons else 0), reasons

def stages_for(event, branch, changed_files):
    docs_only = all(f.startswith('docs/') or f.endswith('.md') for f in changed_files)
    if changed_files and docs_only:
        return ['lint']
    stages = ['lint', 'unit', 'integration']
    main_push = event == 'push' and branch == 'main'
    if main_push or any(f.startswith('src/checkout/') for f in changed_files):
        stages.append('e2e')
    if main_push:
        stages.append('deploy-staging')
    return stages
